export const clinicalReasoningCases: ClinicalReasoningCase[] = clinicalReasoningCaseSeeds.map((caseData) => {
  const diagnosisId = clinicalReasoningDiagnosisMap[caseData.id];
  const diagnosis = searchBank.find((item) => item.id === diagnosisId);
  if (!diagnosis) {
    throw new Error(`Missing Clinical Reasoning diagnosis in Search Bank: ${caseData.id} -> ${diagnosisId}`);
  }

  return {
    ...caseData,
    diagnosis,
  };
});


export function getClinicalReasoningCase(id: string) {
  return clinicalReasoningCases.find((caseData) => caseData.id === id);
}

export function getClinicalReasoningHistoryAnswer(caseId: string, questionId: string) {
  return getClinicalReasoningCase(caseId)?.historyAnswers[questionId] ?? "N/A";
}
